import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"GR-2: A Generative Video-Language-Action Model with Web-Scale Knowledge for Robot Manipulation","description":"","frontmatter":{"title":"GR-2: A Generative Video-Language-Action Model with Web-Scale Knowledge for Robot Manipulation","arxiv":"2410.06158","date":"2024-10-08","authors":"Chi-Lam Cheang, Guangzeng Chen, Ya Jing, Tao Kong, Hang Li, Yifeng Li, Yuxiao Liu, Hongtao Wu, Jiafeng Xu, Yichu Yang, Hanbo Zhang, Minzhao Zhu","categories":"cs.RO, cs.CV, cs.LG","topics":"视频生成赋能具身智能, 视频生成预训练, 通用操作策略","outline":[2,2]},"headers":[],"relativePath":"papers/2410.06158.md","filePath":"papers/2410.06158.md","lastUpdated":null}'),l={name:"papers/2410.06158.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="gr-2-a-generative-video-language-action-model-with-web-scale-knowledge-for-robot-manipulation" tabindex="-1">GR-2: A Generative Video-Language-Action Model with Web-Scale Knowledge for Robot Manipulation <a class="header-anchor" href="#gr-2-a-generative-video-language-action-model-with-web-scale-knowledge-for-robot-manipulation" aria-label="Permalink to &quot;GR-2: A Generative Video-Language-Action Model with Web-Scale Knowledge for Robot Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2410.06158" target="_blank" rel="noreferrer">2410.06158</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-10-08</td></tr><tr><td><strong>作者</strong></td><td>Chi-Lam Cheang, Guangzeng Chen, Ya Jing, Tao Kong, Hang Li, Yifeng Li, Yuxiao Liu, Hongtao Wu, Jiafeng Xu, Yichu Yang, Hanbo Zhang, Minzhao Zhu（字节跳动 Research，按字母序）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.CV, cs.LG</td></tr><tr><td><strong>一句话</strong></td><td>先在 3800 万条互联网视频（约 500 亿 token）上做「文本 + 首帧 → 未来帧」的自回归生成预训练，再在机器人轨迹上同时微调视频预测与 cVAE 动作轨迹生成，把视频里的动力学先验搬进通用操作策略。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">论文性质</p><p>本文是<strong>技术报告</strong>（arXiv comments 明示 Tech Report），没有传统意义上的组件消融表；除 CALVIN 外的定量结果均以柱状图（Fig. 6/9/10/11）呈现，正文只点名了其中一部分数值。本文只引用正文点名的数字，不从图上估读。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>机器人操作长期卡在数据上：真机遥操作采集慢、系统不易扩展，导致「一个模型学一百个任务」这种在语言和视觉领域已成常态的做法在机器人上难以复制。视频生成预训练是一条绕过去的路——互联网视频里天然含有「给定当前画面和一句话，接下来会发生什么」的监督信号，而这正是动作预测所需的环境动力学。</p><p>GR-2 要回答的问题很具体：把视频生成预训练的规模从 GR-1 的 80 万条推到 3800 万条，配合一套能让预训练知识「无损」转到下游的架构，能否得到一个真正可用的通才操作智能体？重要性不在于单个 benchmark 分数，而在于它给出了一个可核对的规模化答案：105 个真机任务平均成功率 97.7%，每任务只用约 50 条轨迹时仍有 73.9%，以及在 122 个物体（其中 67 个训练未见）的端到端抓取分拣上平均 79.0%。如果这些数字站得住，「多采一点视频比多采一点轨迹更划算」就从口号变成了工程结论。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>最直接的前作是同组的 GR-1：GPT 式框架，先在视频上做未来帧预测预训练，再在机器人数据上联合预测帧与动作，在 CALVIN 上表现良好。它的限制有两条：预训练视频只有 80 万条，规模远不足以覆盖日常活动的分布；预训练与微调之间的架构切换不完全平滑，知识转移有损耗。</p><p>另一条主线是把互联网预训练的视觉-语言模型直接微调成策略：RT-2、RoboFlamingo、OpenVLA 等把 VLM 的语义泛化带进机器人，但它们继承的是「图文对齐」的知识，而不是「状态如何演化」的知识——一张图和一句话的对应关系无法告诉模型松手后杯子会掉。还有一类把视频预测模型与逆动力学模型或 MPC 拼接的方法（UniPi、Learning Universal Policies、MaskViT 等），推理时要先跑完整的生成过程，代价高且动作精度受生成精度制约。VIPER 则把视频预测模型当作无动作奖励信号去训 RL 策略，路线不同但同样承认视频含有可用于控制的信息。</p><p>再有就是表征预训练路线（R3M、VC-1、Voltron、MVP、RPT）：用掩码建模或对比学习先学视觉表征，再接策略。这类方法的问题是表征目标与控制目标脱节，学到的多是静态信息。GR-2 的定位是：不学表征、直接学生成，并且把生成头在微调阶段保留下来与动作头并行输出。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>站在 GR-1 之后、GR-2 之前的位置，已知的事实是：视频预训练确实带来了增益，但增益的天花板在哪里没人知道；同期语言与视觉领域的经验一致指向「同一目标、更大数据、更大模型」能持续兑现收益。于是第一个自然动作是把预训练数据从 80 万推到 3800 万，并检查 scaling 曲线是否还在下降——这就是 Fig. 11(a)(b)(c) 三条验证损失曲线的动机。</p><p>第二个问题随之而来：数据量上去之后，瓶颈会移到「预训练与微调的接口」上。如果视频用连续潜变量表示，预训练用一套 head、微调换另一套，中间必然掉信息。选择 VQGAN 把图像离散化，好处是预训练和微调都在同一个 token 空间里做自回归预测，接口天然一致；代价是重建上限受 tokenizer 限制，所以 tokenizer 要用互联网数据加域内机器人数据一起训并冻结。</p><p>第三个问题是动作侧。单步动作在真机上会抖，且高频控制要求推理不能太慢。已有的 ACT/action chunking 经验表明预测动作块更平滑；用 cVAE 生成轨迹既能表达多模态又能一次出一段。最后是部署：Cartesian 轨迹到关节指令还有一层，需要全身控制与轨迹优化把碰撞约束和可操作度纳入进来，才能在 200 Hz 上稳定跟踪。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>一个足够大的「看图说话预测下一帧」模型，被迫在参数里编码「物体被推会滑、被抓会跟着手走、盖子拧开后会分离」这类规律；这些规律与动作预测所需的知识是同一套。因此不必设计特殊的表征目标，只要让预训练与微调共用同一个 token 空间和同一套 transformer，动作头就能直接读取这些参数里的先验。方法奏效的核心是接口的一致性，而不是某个模块的巧思。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「把杯盖拧开并放到桌上」为例：</p><ol><li><strong>输入</strong>：语言指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span></span></span></span>、观测序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">h</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>（头部静态相机 + 腕部相机）、机器人状态序列 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathbf">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">h</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>（末端位置、旋转、二值夹爪状态）。</li><li><strong>编码</strong>：语言用冻结的 CLIP 文本编码器 tokenize；每帧图像用冻结的 VQGAN 转成离散 token；状态经可训练线性层编码（仅微调阶段可训）。</li><li><strong>预训练（阶段一）</strong>：GPT 式 transformer 输入文本与图像 token，输出未来帧的离散 token，再由 VQGAN 解码器还原图像。数据来自 HowTo100M、Ego4D、Something-Something V2、EPIC-KITCHENS、Kinetics-700 等人类活动数据集，加上 RT-1 与 Bridge 等公开机器人数据；经过手部过滤（MediaPipe）与重新加字幕（Open-Sora 流水线）后共 3800 万片段。</li><li><strong>微调（阶段二）</strong>：同一模型接收多视角图像序列，输出每个视角的未来图像与一条动作轨迹 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>；动作轨迹由 cVAE 生成。作者强调生成轨迹而非单步动作对平滑性与实时性都是关键。</li><li><strong>数据增强</strong>：为了泛化到未见场景，训练时用一个扩散模型（自采物体集 + Open Images 训练）在指定区域插入新物体，用 SAM 抠出背景区域替换，再用 Latte 视频生成模型以原视频与修改后的首帧为条件生成增强视频，保持机器人运动不变。</li><li><strong>部署</strong>：7-DoF Kinova Gen3 + Robotiq 2F-85。模型输出 Cartesian 轨迹，先做平滑与连续性优化，再由全身控制算法转成关节指令，以 200 Hz 执行，优化中包含碰撞约束与可操作度。</li></ol><p>默认 GR-2 共 230M 参数，其中 95M 可训练。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化很轻，只有策略的定义：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">h</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">h</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span></span></span></span></span></p><p>以及微调阶段的双输出形式</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">h</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight">h</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord">.</span></span></span></span></span></p><p>值得展开的直觉在于第二个式子的乘积结构。预训练阶段模型学的是条件分布 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2952em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">≤</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2452em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>；微调阶段把动作作为额外输出挂上去，等价于让同一组隐状态同时支撑「未来长什么样」和「现在该怎么动」。作者观察到生成视频与真实 rollout 高度一致，并据此断言「预测的动作是在复现预测视频里的轨迹」——按上式，这只能说明两个输出头共享的隐状态一致，并不构成「视频指导了动作」的因果证据；这一区分在 §9 会展开。</p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">h</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 分别是历史长度与动作块长度；VQGAN 的离散化让预训练目标退化成标准的交叉熵下一 token 预测，因此扩数据、扩模型的收益可以直接用验证损失衡量，这就是 scaling 实验的可比性来源。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：能同时学会多少任务？</strong> 采集 105 个桌面任务、8 类技能（抓、放、拧开、拧上、开、关、按、倒）的遥操作数据，共约 4 万条轨迹（平均每任务 400 条），另做 1/8 子集（约每任务 50 条）。结论：Simple 设定下 97.7%；仅用 50 条/任务时仍有 73.9%。</p><p><strong>问题二：能泛化到什么程度？</strong> 三档递进的分布外设定——未见背景（换两块与训练纯色背景差异极大的桌布）、未见环境（两个未见厨房，含场景相关干扰物）、未见操作（未见类别与未见实例的物体，指令也未见）。结论：未见背景 71.4%、未见环境 71.7%，都是 GR-1 的两倍；加数据增强后未见环境 87.0%，三档平均 74.7%；未见操作最难，55.8%，典型失败是抓不住新形状物体和选错物体。</p><p><strong>问题三：工业场景可用吗？</strong> 端到端分拣：源筐到目标筐，指令只有一句「move any object from the right basket to the left basket」，训练用 55 个物体约 9.4 万条抓放轨迹，评测覆盖 122 个物体（67 个未见），并设置两个物体数量翻倍的杂乱设定。结论：平均成功率从 GR-1 的 33.3% 提升到 79.0%，且未见与杂乱设定的成功率与 Seen 设定相当；透明、可形变、反光物体都能处理。</p><p><strong>问题四：仿真基准上的位置？</strong> CALVIN 的 <strong>ABCD→D</strong> 划分（超过 2 万条示范、34 个任务、1000 条指令链），与 RT-1、MT-ACT、HULC、RoboFlamingo、GR-1 比较：1 个任务成功率从 GR-1 的 94.9% 提到 98.6%，5 个任务从 73.1% 提到 85.9%，平均长度从 4.21 提到 4.64。</p><p><strong>问题五：还能继续扩吗？</strong> 预训练四个规模（可训练参数 30M / 95M / 312M / 719M），在 Ego4D、RT-1 与自采机器人数据三个验证集上视频预测损失随规模单调下降；微调后在 §3.1 的部分设定上成功率也随规模上升。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：GR-2 把视频生成预训练从 80 万条推到 3800 万条（约 500 亿 token），并用 VQGAN 离散 token 让预训练与微调共用同一个自回归接口。105 个真机任务平均 97.7%，每任务仅 50 条轨迹时仍有 73.9%，说明视频先验显著降低了新技能的采集成本。三档泛化设定上未见背景 71.4%、未见环境 71.7%（GR-1 的两倍），加上专门的插物体/换背景数据增强后三档平均 74.7%。端到端分拣覆盖 122 个物体、67 个未见，平均成功率 33.3% → 79.0%，且未见与杂乱设定几乎不掉。四档模型规模上视频验证损失与真机成功率同向变化，是本文对「继续扩」最直接的支持。</p><p><strong>3 句话版</strong>：把「预测下一帧」当作机器人策略的预训练目标，规模一上去就能兑现成真机成功率。关键工程选择是用离散视觉 token 统一预训练与微调接口，并用 cVAE 输出动作块以保证平滑与实时。泛化提升中有相当一部分来自专门设计的数据增强，而非纯粹的视频先验。</p><p><strong>1 句话版</strong>：视频生成预训练在 3800 万条量级上，把「学会一个新任务」的真机数据成本压到了每任务 50 条。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>视频生成质量是动作质量的可优化代理</strong>。论文在 §3.4 明确写道，预测视频与真实 rollout 高度一致，因此「可以通过不断改进视频生成来持续改进动作预测」。整个技术路线的长期价值都押在这条上——如果它不成立，扩视频数据就只是在买一个通用视觉编码器，收益会很快饱和。</p><p>它在实践中很可能不成立。生成视频与 rollout 一致，最简单的解释是两个头共享隐状态、都在拟合同一批演示数据，因此彼此相关；相关不蕴含「改进前者会改进后者」。同期工作提供了方向相反的直接证据：VidMan（<a href="/notes/papers/2411.09153">2411.09153</a>）在帧采样间隔的消融里发现，间隔从 1 增到 3 时 Bridge 上的 FID 从 29.5 恶化到 38.4、FVD 从 327 涨到 376，而 CALVIN 平均长度却从 2.24 提升到 3.42——视频指标越差，动作越好。论文为自己的说法提供的证据全部是定性图（Fig. 12–17），既没有「视频 FVD 与成功率的相关性」这类曲线，也没有「冻结动作头、只改进视频头」的对照，因此这条最有战略意义的结论恰恰是全文证据最薄的一条。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 3800 万条预训练，一周内可做：</p><ul><li>取任一开源的视频-动作联合模型（GR-1 系列或 VidMan 的公开实现），在 CALVIN ABC→D 上正常训练，沿途保存 10–15 个 checkpoint。</li><li>对每个 checkpoint 同时测两组量：视频侧的 FVD/PSNR（在留出的 CALVIN 视频上）与动作侧的平均完成长度。</li><li>度量：两条曲线在<strong>同一模型的训练轨迹内</strong>的秩相关（Spearman <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>）。注意必须在同一模型内比较，跨模型规模比较会被容量混杂。</li><li>判据：若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.7</span></span></span></span>，本文的代理假设成立，「改进视频即可改进动作」是可操作的工程路线；若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 在 0 附近或为负，则该假设只在特定训练阶段成立，扩视频质量的边际收益需要重新评估。附加检查：把动作头冻结、只继续训视频头若干步，看成功率是升是降。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释：<strong>GR-2 相对 GR-1 的增益主要来自机器人侧数据与数据增强，而非 3800 万条互联网视频</strong>。GR-2 相对 GR-1 同时改了三件事——预训练视频 0.8M → 38M、架构（VQGAN 离散 token + cVAE 动作块）、机器人数据规模与增强流水线——全文没有任何一项把它们分开的对照实验。而两条线索指向后两者：其一，三档泛化设定的头条数字 74.7% 是 <strong>GR-2 w/ DA</strong> 取得的，而数据增强做的恰好是「插入新物体、更换背景」，与「未见背景/未见环境含干扰物」这两个测试设定在分布上高度同构；其二，CALVIN 用的是 <strong>ABCD→D</strong> 划分，训练环境已包含 D，本身不测环境泛化，因此 4.64 这个数字无法佐证视频先验带来的跨环境迁移。</p><p>设计一个能证伪的实验：固定架构、固定机器人数据与增强流水线，只把预训练视频量在 {0, 0.8M, 8M, 38M} 四档上扫，同时在两类评测上读数——(a) 未见背景/环境（与增强分布同构）；(b) 未见操作（增强流水线覆盖不到，因为它不会造出新的技能）。若视频量对 (a) 的斜率很小而对 (b) 很大，则「互联网视频提供的是动力学而非外观覆盖」成立；若两条曲线都平、增益几乎全由是否开启增强决定，那么本文的核心叙事需要改写为「合成数据增强 + 更大机器人数据集」。可预测的失效条件也随之清楚：当测试分布的变化是<strong>技能层面</strong>而不是<strong>外观层面</strong>时，方法应当明显退化——论文自己给出的 55.8% 未见操作成功率与另外两档 70%+ 的落差，正是这一预测的初步印证。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：视频生成头在部署时基本是个副产品——模型输出未来帧，但没人用它。而论文最有趣的观察恰恰是「预测视频与真实 rollout 高度一致」。一致性一旦被破坏，就是模型在告诉你它的世界模型和现实对不上，而这正是失败即将发生的时刻。当前范式把这一信号浪费掉了。</p><p><strong>(b) 新的 framing 与可借的工具</strong>：把生成头从「预训练脚手架」重新定位成<strong>运行时的自监督裁判</strong>：在线比较 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 时刻预测的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9162em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">o</span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 与实际观测到的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6528em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>，用 token 级的负对数似然作为分布偏移与失败的预警量。由于图像被 VQGAN 离散化，似然是现成可算的，不需要任何额外训练。可借鉴的相邻领域工具有三类：模型预测控制里的残差故障检测（residual-based fault detection），共形预测（conformal prediction）用于把似然阈值校准成有覆盖率保证的报警器，以及主动学习里的不确定性采样，用来决定「哪一条失败轨迹最值得人类补一条演示」。</p><p><strong>(c) 第一个实验</strong>：在最难的未见操作设定（55.8%）上，记录每次 rollout 每一步的真实下一帧在模型下的 token 平均负对数似然，标签是该 rollout 最终成功与否，计算「在失败发生前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步用似然预测失败」的 AUROC。若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span></span></span></span> 步时 AUROC 明显高于 0.5，就得到一个零额外成本的在线安全监控器；进一步可以把它接成闭环——似然超阈值时触发重规划或请求人类接管，并把这些片段优先送进下一轮微调。这个方向的价值在于它换掉了评价目标：不再问「成功率能不能再高几个点」，而问「模型能不能知道自己什么时候要失败」。</p>',51)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
